<?php
session_start();
require_once __DIR__ . '/../includes/auth.php';
requireRole('patient');
$query = $pdo->prepare('SELECT a.appointment_date, a.reason, a.status, d.doctor_name, dep.department_name, h.hospital_name FROM appointments a JOIN patients p ON p.id = a.patient_id JOIN hospitals h ON h.id = a.hospital_id LEFT JOIN doctors d ON d.id = a.doctor_id LEFT JOIN departments dep ON dep.id = d.department_id WHERE p.user_id = :user_id ORDER BY a.appointment_date DESC');
$query->execute([':user_id' => $_SESSION['user_id']]); $appointments = $query->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'My Appointments'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Patient space</p><h1 class="h2">My Appointments</h1></div><a class="btn btn-primary" href="<?= e(appUrl('patient/book_appointment.php')) ?>">Request appointment</a></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Hospital</th><th>Date</th><th>Doctor</th><th>Department</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach ($appointments as $appointment): ?><tr><td><?= e($appointment['hospital_name']) ?></td><td><?= e($appointment['appointment_date']) ?></td><td><?= e($appointment['doctor_name'] ?? 'Awaiting Front Desk assignment') ?></td><td><?= e($appointment['department_name'] ?? 'Pending routing') ?></td><td><?= e($appointment['reason']) ?></td><td><?= e($appointment['status']) ?></td></tr><?php endforeach; ?><?php if (!$appointments): ?><tr><td colspan="6" class="text-muted">No appointments found.</td></tr><?php endif; ?></tbody></table></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
